		path: '/booking#application-defined-presets',
		category: 'Dual dates and booking',
		text: "Corresponding dates, availability filters, range limits, cell templates and quick selections. A preset contains label and value: a mode-specific DatePickerValue or a synchronous resolver. It receives calendar, one-based today, selectionMode and outputFormat when activated. Static fiscal dates are specific to a calendar and output format. Presets validate before committing, mark the control touched, respect closeOnSelection and cannot bypass readonly/disabled state. Failed resolvers or invalid selections leave the model unchanged. Today is read from the local system date at activation. import type { DatePickerConfig, DatePresetContext, DatePickerValue } from 'ngx-nepali-dualpicker';\nimport { DateCalculator, formatPickerDate } from 'ngx-nepali-dualpicker/core';\nfunction monthValue(context: DatePresetContext, offset: number): DatePickerValue {\n  const ordinal = context.today.year * 12 + context.today.month - 1 + offset;\n  const year = Math.floor(ordinal / 12), month = ((ordinal % 12 + 12) % 12) + 1;\n  const day = context.calendar === 'BS'\n    ? DateCalculator.getDaysInBsMonth(year, month) : DateCalculator.getDaysInAdMonth(year, month);\n  return { start: formatPickerDate({year, month, day: 1}, context.outputFormat), end: formatPickerDate({year, month, day}, context.outputFormat) };\n}\nconst config: DatePickerConfig = {\n  calendar: 'BS', selectionMode: 'range',\n  presets: [\n    { label: 'This month', value: context => monthValue(context, 0) },\n    { label: 'Last month', value: context => monthValue(context, -1) },\n    { label: 'Fiscal period', value: { start: '2082-04-01', end: '2083-03-31' } },\n  ],\n};",
