		path: '/api#exports',
		category: 'interface API',
		text: 'DatePickerTheme Theme Configuration for Nepali Date Picker\nProvides full customization capabilities for colors, spacing, typography, and animations export interface DatePickerTheme {\n\t// Color scheme\n\tcolors: {\n\t\tprimary?: string;\n\t\tprimaryHover?: string;\n\t\tprimaryLight?: string;\n\t\tsecondary?: string;\n\t\tbackground?: string;\n\t\tsurface?: string;\n\t\tborder?: string;\n\t\ttext?: string;\n\t\ttextSecondary?: string;\n\t\ttextDisabled?: string;\n\t\terror?: string;\n\t\tsuccess?: string;\n\t\tselectedBackground?: string;\n\t\tselectedText?: string;\n\t\thoverBackground?: string;\n\t\ttodayText?: string;\n\t\trangeBackground?: string;\n\t\trangeHoverBackground?: string;\n\t};\n\n\t// Spacing\n\tspacing: {\n\t\tcontainerPadding: string;\n\t\tdateGap: string;\n\t\theaderPadding: string;\n\t\tpickerGap: string;\n\t};\n\n\t// Typography\n\ttypography: {\n\t\tfontFamily: string;\n\t\tfontSize: {\n\t\t\tbase: string;\n\t\t\tsmall: string;\n\t\t\tlarge: string;\n\t\t};\n\t\tfontWeight: {\n\t\t\tnormal: number;\n\t\t\tmedium: number;\n\t\t\tsemibold: number;\n\t\t\tbold: number;\n\t\t};\n\t};\n\n\t// Border radius\n\tborderRadius: {\n\t\tsmall: string;\n\t\tmedium: string;\n\t\tlarge: string;\n\t\tfull: string;\n\t};\n\n\t// Shadows\n\tshadows: {\n\t\tdropdown: string;\n\t\tselected: string;\n\t};\n\n\t// Transitions\n\ttransitions: {\n\t\tdefault: string;\n\t\tfast: string;\n\t\tslow: string;\n\t};\n\n\t// Dimensions\n\tdimensions: {\n\t\tdateSize: string;\n\t\tcontainerWidth: string;\n\t\tcontainerMaxHeight: string;\n\t\ticonSize: string;\n\t};\n}',
